//! Generates the TypeScript contract types in `packages/contracts` from the Rust contract types.
//!
//! Tooling only: the engine and the WASM adapter do not depend on this crate. Generated files are
//! committed; `tests/drift.rs` fails when they no longer match the Rust types.

use std::fs;
use std::io;
use std::path::Path;

use arqlet_model::{
    ConfigSet, Intent, LayoutStrategy, Measurement, Orientation, Overview, OverviewIntent,
    OverviewRequest, PublicationEnvelope, Snapshot,
};
use arqlet_reference::{document::ReferenceDocument, Report};
use arqlet_scene::Scene;
use ts_rs::{Config, TS};

/// Writes every contract type reachable from the roots, plus `index.ts`, into `dir`.
///
/// Existing `.ts` files in `dir` are removed first, so a renamed or removed type cannot leave a stale file.
pub fn export_to(dir: &Path) -> io::Result<()> {
    fs::create_dir_all(dir)?;
    for entry in fs::read_dir(dir)? {
        let path = entry?.path();
        if path.extension().is_some_and(|ext| ext == "ts") {
            fs::remove_file(path)?;
        }
    }
    let config = Config::new().with_out_dir(dir);
    Orientation::export_all(&config).map_err(io::Error::other)?;
    LayoutStrategy::export_all(&config).map_err(io::Error::other)?;
    Snapshot::export_all(&config).map_err(io::Error::other)?;
    Measurement::export_all(&config).map_err(io::Error::other)?;
    Intent::export_all(&config).map_err(io::Error::other)?;
    PublicationEnvelope::export_all(&config).map_err(io::Error::other)?;
    Scene::export_all(&config).map_err(io::Error::other)?;
    ConfigSet::export_all(&config).map_err(io::Error::other)?;
    OverviewIntent::export_all(&config).map_err(io::Error::other)?;
    Overview::export_all(&config).map_err(io::Error::other)?;
    OverviewRequest::export_all(&config).map_err(io::Error::other)?;
    ReferenceDocument::export_all(&config).map_err(io::Error::other)?;
    Report::export_all(&config).map_err(io::Error::other)?;

    for entry in fs::read_dir(dir)? {
        let path = entry?.path();
        if path.extension().is_some_and(|ext| ext == "ts") {
            let contents = fs::read_to_string(&path)?;
            let normalized = contents
                .lines()
                .map(|line| line.trim_end_matches(|c| c == ' ' || c == '\t'))
                .collect::<Vec<_>>()
                .join("\n");
            fs::write(path, format!("{normalized}\n"))?;
        }
    }

    let mut names: Vec<String> = fs::read_dir(dir)?
        .map(|entry| entry.map(|e| e.file_name().to_string_lossy().into_owned()))
        .collect::<Result<_, _>>()?;
    names.retain(|name| name.ends_with(".ts") && name != "index.ts");
    names.sort();
    let mut index = String::from("// Generated by crates/contracts. Do not edit by hand.\n");
    for name in &names {
        index.push_str(&format!(
            "export * from './{}';\n",
            name.trim_end_matches(".ts")
        ));
    }
    fs::write(dir.join("index.ts"), index)
}
